function_name='HAL_UART_Receive_IT' replacement_code='#include "HAL_BE.h"

HAL_StatusTypeDef HAL_UART_Receive_IT(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size)
{
    /* Check that a Rx process is not already ongoing */
    if (huart->RxState == HAL_UART_STATE_READY)
    {
        if ((pData == NULL) || (Size == 0U))
        {
            return HAL_ERROR;
        }

        /* Process Locked */
        __HAL_LOCK(huart);

        huart->pRxBuffPtr = pData;
        huart->RxXferSize = Size;
        huart->RxXferCount = Size;

        /* Set the UART state to ready for reception */
        huart->RxState = HAL_UART_STATE_BUSY_RX;

        /* Process Unlocked */
        __HAL_UNLOCK(huart);

        /* Use HAL_BE_In for POSIX-compatible input */
        HAL_BE_In(pData, Size);

        /* Call the reception complete callback */
        if (huart->RxISR != NULL)
        {
            huart->RxISR(huart);
        }

        return HAL_OK;
    }
    else
    {
        return HAL_BUSY;
    }
}' reason='The original HAL_UART_Receive_IT function contains hardware-dependent operations that cause emulator errors. This replacement removes all hardware register accesses and uses HAL_BE_In for POSIX-compatible input while preserving the UART state machine and callback mechanism. The function maintains the same API and error handling but replaces hardware polling with a clean POSIX implementation.'
